        if(L.rank&&L.rank[av]!=null&&L.rank[bv]!=null)r=L.rank[av]-L.rank[bv];
        else if(L.rank&&L.rank[av]!=null)r=-1;
        else if(L.rank&&L.rank[bv]!=null)r=1;
