    var _modeToolbar=tableModeToolbar(chart,settings,'aggregate');
    // 层级下钻 v2（P3，docs/table-crosstable-p3.md §2）：不再有独立的「下钻表」布局
    // （旧 renderHierarchyDrill 劫持整卡成死「下钻」列，已废）。层级配置
    // （ds.hierarchy / editor.data.hierarchy 的 parent→child 边）让**最深行维的单元格**
    // 出现下钻入口：点击 = 行区追加子层级，drillSteps 记 {col,value,child}（value=被点
    // 父值），整表经统一路由重新渲染（1 维→平表，2 维→嵌套平铺/3D 矩阵，≥3 维→ND
    // 长表），面包屑逐级回退。
    var tblDrillSteps=Array.isArray(settings.drillSteps)?settings.drillSteps.filter(function(s){return s&&s.col&&s.child;}).slice():[];
    function tblHierChildOf(col){
      var dsx=data&&data.datasetId?datasets.get(data.datasetId):null;
      var h=(dsx&&Array.isArray(dsx.hierarchy)&&dsx.hierarchy.length)?dsx.hierarchy:(Array.isArray(data.hierarchy)?data.hierarchy:null);
      if(!h)return null;
      for(var i=0;i<h.length;i++){var e=h[i];if(e&&e.parent===col&&e.child)return e.child;}
      return null;
    }
    // 明细跳转（P3，docs/table-crosstable-p3.md §3.4）：聚合行点击 → 明细视图 + 按
