    // 净流入占比 1.6% 显示成 430%，2026-09-15 真机）。
    var rows=await adapter.aggregate(data,data.dimension,measures,(data.aggregations&&typeof data.aggregations==='object'&&!Array.isArray(data.aggregations))?data.aggregations:data.aggregation||'sum',null,{fullSet:true});
    // breakdown（分组维度）：只来自 roles.breakdown——层级不再自动推导 bd（P3 裁决：
    // 层级对表格卡的唯一作用 = 最深行维可点击下钻，不再改写行列结构）。
    // ①读者字段自选：会话 bd:false = 隐藏列维（塌回平表——既有语义：删列区芯片）。
    var bd=(data.roles||{}).breakdown;
    if(!sessionBdOn(sessionViewOf(chart)))bd=null;
    // 行区维度 = 数据窗格「行」区声明 + 下钻子级（后进）；后续所有路由与渲染只看它。
    var _tblDims=(data.dimensions&&data.dimensions.length)?data.dimensions.slice():[data.dimension].filter(Boolean);
