    // 平表 / 分组 / 1D 矩阵三个分支（行形状同为 {label, breakdown, values}）；
    // 嵌套 / 3D 分支自取数，各在分支内按自己的行集再求值。副列是显示层——
    // 不进 fetchAggregate 的 reqBases、不进服务端表声明（chart-adapter 零改动）。
    var subEntries=subTableEntries(settings,data,measures);
    var subBucket=(data.dimensionBucket&&data.dimensionBucket.bucket)||'';
    var subPlan=subEntries.length?subPlanFor(subEntries):[];
    var subResults=subEntries.length?subEvaluate(subEntries,rows.slice(),{
      labelOf:function(r){return r.label;},
      partOf:function(r){return (r&&r.breakdown!=null)?r.breakdown:'';},
      valOf:function(r,m){var mi=measures.indexOf(m);return mi>=0?r.values[mi]:null;},
      aggOf:function(m){return tblAggMethodOf(data,m);},
      aggKey:function(a,c){return adapter.derivedAggKey(a,c);},
      evalFn:adapter.derivedEvaluate.bind(adapter),
      dim:data.dimension,bucket:subBucket,
      warn:function(msg){if(global.console&&console.warn)console.warn(msg);}
    }):null;
    function tblAggMethodOf(d,m){
      var aggs=(d&&d.aggregations&&typeof d.aggregations==='object'&&!Array.isArray(d.aggregations))?d.aggregations:null;
      return (aggs&&(aggs[m]||d.aggregation))||d.aggregation||'sum';
    }
    // 列区透视（0 行维 + 1 列维，Quick BI「仅列维交叉」同款）：行区为空、列区有
    // 芯片时，行 = 指标、列 = 列维值。adapter.aggregate 对空维度早退返回 []
    // （columns.indexOf('')<0），矩阵门恒失效 → 整表塌回只剩指标列的平表（用户报
    // 「把维度放到列上之后表头显示不出来」）。这里按列维单独取数，展开成矩阵模型
    // 输入（label=指标名、breakdown=列维值、values 稀疏位），复用 1D 矩阵的表头/
    // 合计/分页/导出全管道。派生/副列在上方空行集上已求值 = 空，天然不参与。
    var tblBdOnly=false;
    // bd=指标名称（虚拟列）不在此取数（服务端无此列）——0 行维 + 仅指标名称在列区
    // 的退化形态交由下方 D 闸给可行动引导。
    if(bd&&!_tblDims.length&&bd!==MN_DIM){
      tblBdOnly=true;
      var _coRaw=await adapter.aggregateTable(data,[bd],measures,tblAggMethodOf(data,measures[0]||''));
      if(renderVersions.get(chart)!==version)return;
      rows=[];
      (_coRaw||[]).forEach(function(r){
        var _bv=String(r.path[0]==null?'':r.path[0]);
        measures.forEach(function(m,vi){
          rows.push({label:m,breakdown:_bv,values:measures.map(function(_x,j){return j===vi?((r.values&&r.values[vi]!=null)?r.values[vi]:null):null;})});
        });
      });
    }
    // ---- WP-11 总计计算方式：三载体解析 -------------------------------------
