      if(!rows.length){host.innerHTML=tableTopBar(modeBar,tools)+statsBar+'<div class="ai-report-empty">没有匹配的行</div>';bindServerDetailEvents(host,chart,dataset,cols);if(state.statsOn)fillServerDetailStats(host,chart,dataset,cols,state,filter);return;}
