      var sEng=condBranchEngine(condEntriesFor(chart,settings,{},cols,false),condColStats(rows,cols,function(r,col){var j=cols.indexOf(col);return j>=0?r[j]:null;}));
      var body=rows.map(function(r){var rget=function(col){var j=cols.indexOf(col);return j>=0?r[j]:null;};return '<tr>'+cols.map(function(c,j){var sdec=sEng.cell(c,r[j],{rowKind:'data',get:rget});return '<td'+condTdStyleAttr(sdec)+'>'+condIconPrefix(sdec)+(sdec&&sdec.hideText?'':cell(c,r[j]))+'</td>'+(hasBar(c)?'<td class="ai-pb-cell">'+pbCellHtml(chart,c,r[j])+'</td>':'');}).join('')+'</tr>';}).join('');
