    pop.appendChild(apply);
    apply.addEventListener('click',function(){data.cardFilter.columns=cols.slice();data.cardFilter.filters=(data.cardFilter.filters||[]).filter(function(f){return cols.indexOf(f.column)>=0;});afterCardFilterChange(blockId);if(pop.parentNode)pop.parentNode.removeChild(pop);});
    pop.addEventListener('click',function(e){if(e.target.closest('[data-cf-close]')&&pop.parentNode)pop.parentNode.removeChild(pop);});
    var r=anchor&&anchor.getBoundingClientRect?anchor.getBoundingClientRect():{bottom:0,left:0};
    pop.style.position='fixed';pop.style.top=(r.bottom+6)+'px';pop.style.left=Math.max(8,Math.min(r.left,global.innerWidth-300))+'px';
    document.body.appendChild(pop);
