    var btn=document.querySelector('[data-layout-toggle]');
    if(btn){
      var on=mode==='page';
      btn.textContent=(on?'✓ ':'')+'合并页签显示';
      btn.classList.toggle('ai-report-layout-active',on);
      btn.title=on?'当前为合并页签显示（一页看完），点击切换为分页':'当前为分页（点击页签切换），点击合并为单页';
    }
