      if(btn){activateTab(btn.getAttribute('data-tab-go'));return;}
      var layout=event.target&&event.target.closest?event.target.closest('[data-layout-toggle]'):null;
      if(layout){setReportLayout(reportLayout()==='page'?'tabs':'page');return;}
