    var CROSS_VIEWS=['heatmap','bar','stackedBar','table'];
    var isCrossView=CROSS_VIEWS.indexOf(chart.viewType)>=0;
    var xTab=['heatmap','table'].indexOf(chart.viewType)>=0;
    var barCross=['bar','stackedBar'].indexOf(chart.viewType)>=0;
