    if(chart.viewType==='table'&&!inUse[MN_DIM]&&chosenMeasures.length)unselGroups.dimension.unshift(MN_DIM);
    // 合成行数指标「记录数」（'*'，SKILL.md：行数是一等指标）：虚拟列——不在
