            if(muted)return '<span class="ai-report-chip ai-report-chip-locked" title="'+escapeHtml(c+'：ID / 忽略字段，不参与图表；如需使用请在「数据源配置」里改角色')+'"><span class="ai-report-chip-kind ai-report-chip-kind-other">其他</span><span class="ai-report-chip-label">'+escapeHtml(colAliasOf(datasetById(data&&data.datasetId),c))+'</span></span>';
            return chipHtml(c,classifyColumn(fullData||data,c),'unselected',data,chart);
