  function semCanMoveTo(col,role){
    // 与画布 canMoveTo 同规则：时间区需值域为时间；有层级连线的维度不允许移出维度。
    if(role==='time'&&(semCanvas.roles[col]||'category')!=='time'&&!semIsTimeValueDomain(semCanvas.ds,col)){
      return {ok:false,reason:'「'+col+'」的值域不是基本时间格式（如 2025-01 / 2025-01-02 / 202501），不能设为「时间」'};
    }
    if(role!=='category'){
      var hasEdge=semCanvas.edges.some(function(e){return e&&(e.parent===col||e.child===col);});
      if(hasEdge)return {ok:false,reason:'该字段已建立层级连线，请先删除连线再移出「维度」'};
    }
    return {ok:true};
  }
  // 改角色的唯一入口（⋯ 菜单与拖拽共用）：守卫拒绝时理由落在该行（hintCol），
  // 通过则走 _semChangeRole（清理指标默认/时间分桶等）并提交重渲染。
  function semApplyRoleChange(col,toRole,stage){
    var old=semCanvas.roles[col]||'category';
    if(semNormRole(old)===semNormRole(toRole))return true;
    var guard=semCanMoveTo(col,toRole);
    if(!guard.ok){semCanvas.hint=guard.reason;semCanvas.hintCol=col;renderSemTable(stage||document.getElementById('ai-sem-stage'));return false;}
    var _crossMeasure=(semNormRole(old)==='measure')!==(semNormRole(toRole)==='measure');
    _semChangeRole(col,old,toRole);
    semCanvas.hint='';semCanvas.hintCol=null;semCommitLive();
    // server 模式跨指标边界（2026-09-21）：角色是显示层声明，服务器已装载的表
    // 不会按新角色重新解析取值——若该列曾有「非数值已按空」，翻成维度也不会把
    // 值变回来，必须重新导入。不说清楚，用户会以为提示徽标是显示 bug。
    if(_crossMeasure&&isServerMode()){
      notify('字段角色已保存。注意：服务器已装载的数据不会按新角色重新解析——若该列带「非数值已按空」警示，请用「替换数据」重新导入本表才能保留全部取值。','info');
    }
    renderSemTable(stage||document.getElementById('ai-sem-stage'));
    return true;
  }
  // 行内 ⋯ 菜单（验收修订 2026-09-13）：「角色」列删除后的等价入口 —— 修改角色
  // （4 项，禁用项带拒绝理由）+ 修改显示名 / 字段说明 / 值别名 / 隐藏 / 恢复原名
  // （2026-09-17：行面的 ✎/↺/说明 独立按钮全部收进这里，行面只留 ⋯ + 引用徽标）。
  // 挂 body 弹层（外点/ESC 关闭，互斥）。
  function openFieldMenuPop(anchor,col){
    if(!anchor||!col)return;
    var cur=semNormRole(semCanvas.roles[col]||'category');
    var renamed=colAliasOf(semCanvas.ds,col)!==col;
    var items=SEM_FIELD_ROLE_OPTIONS.map(function(o){
      var guard=(o.v===cur)?{ok:true}:semCanMoveTo(col,o.v);
      return '<button type="button" class="ai-tbl-pop-menu-item'+(o.v===cur?' is-cur':'')+'" data-sem-role-set="'+o.v+'"'
        +(guard.ok?'':' disabled title="'+escapeHtml(guard.reason)+'"')
        +' title="系统推断'+escapeHtml(semRoleLabelOf(semSystemRole(col)))+'">'+(o.v===cur?'✓ ':'')+o.l+'</button>';
    }).join('');
    var pop=mountTablePop(anchor,'<div class="ai-tbl-pop-head"><span>字段 · '+escapeHtml(colAliasOf(semCanvas.ds,col))+'</span>'
      +'<button type="button" class="ai-detail-style-close" data-tbl-pop-close title="关闭">×</button></div>'
      +'<div class="ai-tbl-pop-body ai-tbl-pop-menu">'+items
      +'<button type="button" class="ai-tbl-pop-menu-item" data-sem-menu-rename>✎ 修改显示名…</button>'
      +(renamed?'<button type="button" class="ai-tbl-pop-menu-item" data-sem-menu-unalias>↺ 恢复原名（'+escapeHtml(col)+'）</button>':'')
      +'<button type="button" class="ai-tbl-pop-menu-item" data-sem-menu-note>📝 '+(fieldNoteOf(semCanvas.ds,col)?'编辑字段说明…':'添加字段说明…')+'</button>'
      +'<button type="button" class="ai-tbl-pop-menu-item" data-sem-menu-valias'+(cur==='category'?'':' disabled title="值别名只对维度字段提供（时间/指标字段不提供）"')+'>⚑ 编辑值别名…</button>'
      +'<button type="button" class="ai-tbl-pop-menu-item" data-sem-menu-hide>'+(colIsHidden(semCanvas.ds,col)?'👁 取消隐藏':'🚫 隐藏字段（不进新增候选）')+'</button></div>');
    pop.querySelector('[data-tbl-pop-close]').addEventListener('click',closeTablePop);
    pop.querySelectorAll('[data-sem-role-set]').forEach(function(b){
      b.addEventListener('click',function(){
        var to=b.getAttribute('data-sem-role-set');
        closeTablePop();
        semApplyRoleChange(col,to);
      });
    });
    pop.querySelector('[data-sem-menu-rename]').addEventListener('click',function(){
      closeTablePop();openColumnAliasModal(semCanvas.ds,col);
    });
    var ubtn=pop.querySelector('[data-sem-menu-unalias]');
    if(ubtn)ubtn.addEventListener('click',function(){
      closeTablePop();
      setColumnAlias(semCanvas.ds,col,null);
      semCanvas.hint='';semCommitLive();
      syncColumnAliasesToAdapter();
      renderSemTableList();renderSemTable(document.getElementById('ai-sem-stage'));
    });
    pop.querySelector('[data-sem-menu-note]').addEventListener('click',function(){
      closeTablePop();openFieldNoteModal(semCanvas.ds,col);
    });
    var vbtn=pop.querySelector('[data-sem-menu-valias]');
    if(vbtn)vbtn.addEventListener('click',function(){
      if(vbtn.disabled)return;
      closeTablePop();openValueAliasModal(semCanvas.ds,col);
    });
    pop.querySelector('[data-sem-menu-hide]').addEventListener('click',function(){
      closeTablePop();
      var to=colIsHidden(semCanvas.ds,col);
      setColHidden(semCanvas.ds,col,!to);
      syncManifest();
      renderSemTableList();
      renderSemTable(document.getElementById('ai-sem-stage'));
    });
  }

  // 维度层级 (hierarchy): only category/ordinal dims can be hierarchy nodes; a
  // node has <=1 parent; acyclic (adapter.validateHierarchy enforces).
  function semCategoryDims(ds,roles){
    var pseudo=semPseudoDs(ds,roles);
    return (adapter.dimensionColumns(pseudo)||[]).filter(function(c){var k=adapter.fieldSemantic(pseudo,c);return k&&(k.kind==='category'||k.kind==='ordinal');});
  }
  function semCatParentMap(){
    var m={};(semCanvas.edges||[]).forEach(function(e){if(e&&e.parent&&e.child)m[e.child]=e.parent;});return m;
  }
  function semCatDimsNow(){
    return semCategoryDims(semCanvas.ds,semCanvas.roles);
  }
  // 兄弟/根排序秩：hierarchyOrder 里的显式顺序优先；不在表里的字段（新加/中途
  // 改角色回维度）退回列序，下一次渲染把推导结果写回，顺序重新变完整。
  function semCatRankMap(cats){
    var rank={};cats.forEach(function(c,i){rank[c]=100000+i;});
    (semCanvas.catOrder||[]).forEach(function(c,i){if(rank[c]!=null&&rank[c]>=100000)rank[c]=i;});
    return rank;
  }
  function semCatChildrenMap(cats,parent,rank){
    var children={};
    cats.forEach(function(c){var p=parent[c]||'';(children[p]||(children[p]=[])).push(c);});
    Object.keys(children).forEach(function(p){
      children[p].sort(function(a,b){return (rank[a]!=null?rank[a]:0)-(rank[b]!=null?rank[b]:0);});
    });
    return children;
  }
  function semCatTreeOrder(){
    var cats=semCatDimsNow();
    var parent=semCatParentMap();
    var children=semCatChildrenMap(cats,parent,semCatRankMap(cats));
    var out=[],seen={};
    function walk(n,d){if(seen[n])return;seen[n]=1;out.push({name:n,depth:d});
      (children[n]||[]).forEach(function(c){walk(c,d+1);});}
    (children['']||[]).forEach(function(r){walk(r,0);});
    cats.forEach(function(n){if(!seen[n])walk(n,0);});
    semCanvas.catOrder=out.map(function(o){return o.name;});
    return out;
  }
  // 拖拽守卫：to 不得是 from 自己或 from 的子孙（否则直接成环）。
  // from 尚不是维度（指标/时间字段拖过来改角色+挂子级）时不做链检测——
  // 非维度字段没有任何边，不可能成为 to 的祖先；旧版在这里直接 return false，
  // 让「拖 ⠿ 改角色+挂子级」永远被假拒（且提示误报成「成环」）。
  function semCanDropCat(from,to){
    var cats=semCatDimsNow();
    if(!from||!to||from===to)return false;
    if(cats.indexOf(to)<0)return false;
    if(cats.indexOf(from)<0)return true;
    var parent=semCatParentMap(),p=to,seen={};
    while(p&&!seen[p]){seen[p]=1;if(p===from)return false;p=parent[p];}
    return true;
  }
  // 落点**只有一种**：把 from 放进 to 里面（成为 to 的子级）。用户决策：删除
  // 行上/行下的「同级排序」落点与左右箭头（层级只表达父子，不表达兄弟顺序）。
  function semClearDropZones(stage){
    if(!stage||!stage.querySelectorAll)return;
    stage.querySelectorAll('.ai-sem-drop-child,.ai-sem-drop-root').forEach(function(n){
      n.classList.remove('ai-sem-drop-child','ai-sem-drop-root');
      n.removeAttribute('data-drop-zone');
    });
  }
  function semShowDropZone(stage,tr,zone){
    if(!tr||tr.getAttribute('data-drop-zone')===zone)return;
    semClearDropZones(stage);
    tr.setAttribute('data-drop-zone',zone);
    tr.classList.add(zone==='root'?'ai-sem-drop-root':'ai-sem-drop-child');
  }
  // 移动后的展示顺序：按旧边重建兄弟组（旧顺序定秩）→ 把 from 从旧兄弟组摘出、
  // 追加为目标组的最后一个子级 → DFS 展开成新顺序（写回 catOrder 后渲染按它定秩复现）。
  function semCatOrderAfterMove(from,to){
    var cats=semCatDimsNow();
    var parent=semCatParentMap();
    var children=semCatChildrenMap(cats,parent,semCatRankMap(cats));
    var oldList=children[parent[from]||'']||[];
    var oi=oldList.indexOf(from);if(oi>=0)oldList.splice(oi,1);
    var tl=children[to]||(children[to]=[]);
    if(tl.indexOf(from)<0)tl.push(from);
    var out=[],seen={};
    function walk(n){if(seen[n]||cats.indexOf(n)<0)return;seen[n]=1;out.push(n);
      (children[n]||[]).forEach(walk);}
    (children['']||[]).forEach(walk);
    cats.forEach(function(n){if(!seen[n])walk(n);});
    return out;
  }
  // 拖拽共用的移动原语：先算新展示顺序（用旧边定秩），再改写边（滤掉旧父边再挂
  // 新父边，1:N 单父不变量）+ 写回 catOrder → 提交 → 重渲染。zone 参数保留但忽略
  // （只剩「放进另一个字段」一种语义）；stage 供调用方传入当前渲染容器。
  function semMoveCatNode(from,to,zone,stage){
    if(!semCanDropCat(from,to))return false;
    var order=semCatOrderAfterMove(from,to);
    semCanvas.edges=(semCanvas.edges||[]).filter(function(e){return !(e&&e.child===from);});
    semCanvas.edges.push({parent:to,child:from});
    semCanvas.catOrder=order;
    semCanvas.hint='';semCommitLive();
    renderSemTable(stage||document.getElementById('ai-sem-stage'));
    return true;
  }
  // 移出层级（回顶层）：箭头删除后唯一的脱层入口 = 把字段拖到「维度」分组表头。
  function semOutdentColumn(col,stage){
    semCanvas.edges=(semCanvas.edges||[]).filter(function(e){return e.child!==col;});
    semCanvas.hint='';semCommitLive();renderSemTable(stage||document.getElementById('ai-sem-stage'));
  }
  // 字段真实示例值（前 N 个不同值）——主视图字段配置 / 合并配置 / 大宽表共用。
  function columnSamples(ds,col,n){
    n=n||3;
    if(!ds)return [];
    var cols=(ds.columns||[]).map(function(c){return typeof c==='object'?c.name:c;});
    var ci=cols.indexOf(col);if(ci<0)return [];
    var rows=ds.rows;if(!Array.isArray(rows))return [];
    var out=[],seen={};
    for(var i=0;i<rows.length&&out.length<n;i+=1){
      var v=rows[i][ci];if(v==null||v==='')continue;
      var k=String(v);if(seen[k])continue;seen[k]=1;out.push(k);
    }
    return out;
  }
  // 示例值单元格：本地有行就用本地（singlefile）；server 报告 manifest 是 schema-only
  // （无 rows），退化为按需向 /datasets/:id/values/:col 拉一次真实取值并缓存。
  // 注意：回填时用两个独立属性（data-sample-ds / data-sample-col）定位，
  // 不用 "ds\u0000col" 当单个属性——HTML 属性值不能含 NUL，会被替换成 U+FFFD 配不上。
  var sampleCache={},samplePending={},sampleFailed={};
  function sampleInnerHtml(vals){
    return (vals&&vals.length)
      ? vals.map(function(v){return '<span class="ai-sem-sample" title="真实数据值">'+escapeHtml(String(v).slice(0,24))+'</span>';}).join('')
      : '<span class="ai-sem-sample-empty">—</span>';
  }
  // ``fallbackId``/``fallbackCol``：本地没有行时改从**另一张表**取样的坐标（宽表配置用它
  // ——未物化的宽表要拿「源表的源列名」去问，而不是合并后的列名，否则服务端 400、单元格
  // 永远停在「…」）。``fallbackCol`` 省略时就用 col 本身。
  function sampleCellHtml(ds,col,fallbackId,fallbackCol){
    var local=columnSamples(ds,col,3);
    if(local.length)return '<td class="ai-sem-row-sample">'+sampleInnerHtml(local)+'</td>';
    var dsId=(ds&&ds.id)||fallbackId||'';
    var fetchVals=(typeof adapter.fetchSampleValues==='function')?adapter.fetchSampleValues
                 :(typeof adapter.fetchColumnValues==='function'?adapter.fetchColumnValues:null);
    if(!dsId||!fetchVals)return '<td class="ai-sem-row-sample">'+sampleInnerHtml([])+'</td>';
    var lookupCol=fallbackCol||col;
    var key=dsId+'\u001f'+lookupCol;
    if(sampleCache[key])return '<td class="ai-sem-row-sample">'+sampleInnerHtml(sampleCache[key])+'</td>';
    // 取样失败必须**看得见、点得动**：旧实现只把 pending 清零，单元格永远停在「…」
    // （假装还在加载），失败原因与重试入口都没有。现在失败态 =「—」+ 点击重试。
    if(sampleFailed[key]){
      return '<td class="ai-sem-row-sample" data-sample-ds="'+escapeHtml(dsId)+'" data-sample-col="'+escapeHtml(lookupCol)+'" data-sample-retry="1">'
        +'<span class="ai-sem-sample-empty" title="示例值读取失败，点击重试">—</span></td>';
    }
    if(!samplePending[key]){
      samplePending[key]=1;
      fetchVals.call(adapter,dsId,lookupCol).then(function(vals){
        sampleCache[key]=(vals||[]).filter(function(v){return v!=null&&v!=='';}).slice(0,3).map(String);
        samplePending[key]=0;delete sampleFailed[key];
        paintSampleCells(dsId,lookupCol,sampleCache[key]);
      }).catch(function(){
        samplePending[key]=0;sampleFailed[key]=1;
        // 失败的单元格换成「—」并留一个可点重试的入口（不再是永久的「…」）。
        var tds=document.querySelectorAll('.ai-sem-row-sample[data-sample-ds]');
        for(var i=0;i<tds.length;i+=1){
          if(tds[i].getAttribute('data-sample-ds')===dsId&&tds[i].getAttribute('data-sample-col')===lookupCol){
            tds[i].setAttribute('data-sample-retry','1');
            tds[i].innerHTML='<span class="ai-sem-sample-empty" title="示例值读取失败，点击重试">—</span>';
          }
        }
      });
    }
    return '<td class="ai-sem-row-sample" data-sample-ds="'+escapeHtml(dsId)+'" data-sample-col="'+escapeHtml(lookupCol)+'"><span class="ai-sem-sample-empty">…</span></td>';
  }
  function paintSampleCells(dsId,lookupCol,vals){
    var tds=document.querySelectorAll('.ai-sem-row-sample[data-sample-ds]');
    for(var i=0;i<tds.length;i+=1){
      if(tds[i].getAttribute('data-sample-ds')===dsId&&tds[i].getAttribute('data-sample-col')===lookupCol){
        tds[i].removeAttribute('data-sample-retry');
        tds[i].innerHTML=sampleInnerHtml(vals||[]);
      }
    }
  }
  // 字段重命名（真实落库）：改列名 + 同步 fieldRoles/measureTypes/columnTypes/
  // hierarchy + 所有图表引用（dimension/measures/roles/dimensionBucket/derived.base）
  // + KPI measure + v4 relations 的 keys[].{a,b}.col + semCanvas 镜像字典。
  function renameColumnEverywhere(ds,oldName,newName){
    if(!ds||!oldName||!newName||oldName===newName)return {ok:false,reason:'名称未变化'};
    var cols=(ds.columns||[]);
    var ci=-1;
    for(var i=0;i<cols.length;i+=1){var n=typeof cols[i]==='object'?cols[i].name:cols[i];if(n===oldName){ci=i;break;}}
    if(ci<0)return {ok:false,reason:'找不到字段 '+oldName};
    var dup=cols.some(function(c){var n=typeof c==='object'?c.name:c;return n===newName;});
    if(dup)return {ok:false,reason:'已存在同名字段 '+newName};
    if(typeof cols[ci]==='object')cols[ci]=Object.assign({},cols[ci],{name:newName});else cols[ci]=newName;
    ['fieldRoles','measureTypes','columnTypes','fieldNotes'].forEach(function(k){
      var o=ds[k];if(o&&Object.prototype.hasOwnProperty.call(o,oldName)){o[newName]=o[oldName];delete o[oldName];}
    });
    (ds.hierarchy||[]).forEach(function(e){if(e.parent===oldName)e.parent=newName;if(e.child===oldName)e.child=newName;});
    if(Array.isArray(ds.hierarchyOrder))ds.hierarchyOrder=ds.hierarchyOrder.map(function(n){return n===oldName?newName:n;});
    // P1: derived declarations too — the row-level operands (``derived.columns``)
    // and the aggregate-level column references (``derived.measures[].expr`` /
    // ``input.col`` / ``timeField``). A rename that missed these left a derived
    // measure silently pointing at a column that no longer exists.
    if(ds.derived){
      var dvd=normalizeDatasetDerived(ds.derived);
      dvd.columns.forEach(function(cdef){
        if(cdef.name===oldName)cdef.name=newName;
        if(cdef.left===oldName)cdef.left=newName;
        if(cdef.right===oldName)cdef.right=newName;
      });
      dvd.measures.forEach(function(node){
        if(node.timeField===oldName)node.timeField=newName;
        if(node.expr)node.expr=exprMap(node.expr,function(n){return n.col===oldName?Object.assign({},n,{col:newName}):n;});
        if(node.input&&node.input.col===oldName)node.input=Object.assign({},node.input,{col:newName});
      });
      ds.derived=dvd;
    }
    (manifest.charts||[]).forEach(function(ch){
      var d=ch&&ch.editor&&ch.editor.data;if(!d)return;
      if(d.dimension===oldName)d.dimension=newName;
      if(Array.isArray(d.dimensions))d.dimensions=d.dimensions.map(function(x){return x===oldName?newName:x;});
      if(Array.isArray(d.measures))d.measures=d.measures.map(function(x){return x===oldName?newName:x;});
      if(d.roles)Object.keys(d.roles).forEach(function(rk){if(d.roles[rk]===oldName)d.roles[rk]=newName;});
      if(d.dimensionBucket){
        if(d.dimensionBucket.source===oldName)d.dimensionBucket.source=newName;
        if(d.dimensionBucket.bucketed===oldName)d.dimensionBucket.bucketed=newName;
      }
      if(d.derived)Object.keys(d.derived).forEach(function(t){var sp=d.derived[t];if(sp&&sp.base===oldName)sp.base=newName;});
    });
    (manifest.kpis||[]).forEach(function(kp){if(kp&&kp.measure===oldName)kp.measure=newName;});
    [manifest.relations,semCanvas.relations].forEach(function(list){
      (list||[]).forEach(function(rel){(rel.keys||[]).forEach(function(k){
        if(k.a&&k.a.ds===ds.id&&k.a.col===oldName)k.a.col=newName;
        if(k.b&&k.b.ds===ds.id&&k.b.col===oldName)k.b.col=newName;
      });});
    });
    if(semCanvas.dsId===ds.id){
      semCanvas.cols=(ds.columns||[]).map(function(c){return typeof c==='object'?c.name:c;});
      ['roles','aggs','decs','ftypes'].forEach(function(k){
        var o=semCanvas[k];if(o&&Object.prototype.hasOwnProperty.call(o,oldName)){o[newName]=o[oldName];delete o[oldName];}
      });
      semCanvas.edges=(ds.hierarchy||[]).slice();
      if(Array.isArray(semCanvas.catOrder))semCanvas.catOrder=semCanvas.catOrder.map(function(n){return n===oldName?newName:n;});
    }
    return {ok:true};
  }
  // 「系统默认角色」：与 semStageDataset 的种子顺序一致 —— 构建期 columnRoles
  // （构建期 profile/编译推断）→ 纯值推断。不能只用 autoRoleFor：server 报告
  // manifest 是 schema-only（无行、无 fieldRoles），numericColumns 无法判定，会把
  // 每个字段都当指标，于是「系统默认」提示永远等于用户选择而永不出现。
  var SEM_TOP_ROLE_MAP={time:'time',measure:'measure',dimension:'category',id:'ignore',ignore:'ignore',ordinal:'category'};
  function semSystemRole(col){
    var top=(manifest.columnRoles||{})[col];
    if(top&&SEM_TOP_ROLE_MAP[top])return SEM_TOP_ROLE_MAP[top];
    return autoRoleFor(Object.assign({},semCanvas.ds,{fieldRoles:{}}),col);
  }
  // 字段表过滤（纯 DOM）：按查询串隐藏不匹配的字段行，并同步隐藏没有可见字段的
  // 角色分组行；右上角显示「匹配 N/M」。不改任何语义，搜索词存在 semCanvas.search，
  // 重渲染后由 applySemFieldFilter 重新套用（否则任何一次提交都会把搜索清掉）。
  function applySemFieldFilter(stage){
    stage=stage||document.getElementById('ai-sem-stage');
    if(!stage)return;
    var q=String(semCanvas.search||'').trim().toLowerCase();
    var rows=Array.prototype.slice.call(stage.querySelectorAll('tbody tr'));
    var shown=0,total=0,group=null,groupHas=false;
    function flushGroup(){if(group){group.hidden=!groupHas;}group=null;groupHas=false;}
    rows.forEach(function(tr){
      if(tr.classList.contains('ai-sem-group-row')){flushGroup();group=tr;groupHas=false;return;}
      if(!tr.classList.contains('ai-sem-row'))return;
      total+=1;
      var nameEl=tr.querySelector('.ai-sem-col-name');
      var origEl=tr.querySelector('.ai-sem-col-orig');
      var roleTag=tr.querySelector('.ai-sem-role-tag');
      var name=((nameEl&&nameEl.textContent)||'')+' '+((origEl&&origEl.textContent)||'')+' '+((roleTag&&roleTag.textContent)||'');
      var hit=!q||String(name).toLowerCase().indexOf(q)>=0;
      tr.hidden=!hit;
      if(hit){shown+=1;groupHas=true;}
    });
    flushGroup();
    // 派生区（计算列/派生指标）是独立的段落，按同一个查询串过滤它们的行。
    var derWrap=stage.querySelector('.ai-sem-derive-wrap');
    if(derWrap){
      var anyDer=false;
      ['ai-sem-derive-row'].forEach(function(cls){
        Array.prototype.slice.call(derWrap.querySelectorAll('[data-der-block] .'+cls)).forEach(function(el){
          var hit=!q||String(el.textContent||'').toLowerCase().indexOf(q)>=0;
          el.hidden=!hit;if(hit)anyDer=true;
        });
      });
      if(anyDer){shown+=1;}
    }
    var countEl=stage.querySelector('.ai-sem-search-count');
    if(countEl)countEl.textContent=q?('匹配 '+shown+' / '+total):'';
  }
  // 数据预览：字段配置旁边必须能「看一眼真实数据」（传统 BI 的标配）。服务端走
  // POST /datasets/:id/rows（有界 pageSize ≤100），singlefile 直接切内存行。
  // 数据管理弹层（2026-09-28）：旧「数据预览 · 前 50 行只读」升级为可筛选、
  // 可删行的管理面。真删除两条路径：选中行（server 走 rowids；本地走原行索引
  // 降序 splice）与筛选命中行（谓词数组与聚合同一条编译——服务端
  // _filter_clause / 本地 adapter.filteredRows，同一 {column,op,value} 形状）。
  // 服务端删除后的收尾与 applyUpdatedDataset 同一契约：示例值/列统计失效 +
  // 重渲本表卡片 + rowCount 镜像进本页 manifest（防后续 syncManifest 用旧值
  // 覆盖服务端真值）。singlefile 修改立即生效于本页，经既有保存通道固化。
  function openDataPreview(d){
    if(!d||!d.id)return;
    var cols=(d.columns||[]).map(function(c){return typeof c==='object'?c.name:c;});
    var srv=isServerMode();
    var PAGE=50;
    var st={page:1,total:null,filters:[],sel:{},rowIds:[],busy:false};
    var OPS=[['eq','等于'],['ne','不等于'],['contains','包含'],['gt','大于'],
             ['lt','小于'],['is null','为空'],['is not null','不为空']];
    var mask=document.getElementById('ai-data-preview');
    if(mask&&mask.parentNode)mask.parentNode.removeChild(mask);
    mask=document.createElement('div');
    mask.id='ai-data-preview';
    mask.className='ai-data-preview-mask';
    mask.setAttribute('data-ai-runtime-transient','true');
    mask.innerHTML='<div class="ai-data-preview-card ai-data-manage-card">'
      +'<div class="ai-data-preview-head"><span class="ai-data-preview-title">数据管理 · '+escapeHtml(d.label||d.id)+'</span>'
      +'<span class="ai-data-preview-meta" data-dm-meta></span>'
      +'<button type="button" class="ai-report-icon-button" data-preview-close title="关闭">×</button></div>'
      +'<div class="ai-dm-toolbar">'
      +'<select class="ai-dm-fcol" data-dm-fcol>'+cols.map(function(c){return '<option>'+escapeHtml(c)+'</option>';}).join('')+'</select>'
      +'<select class="ai-dm-fop" data-dm-fop>'+OPS.map(function(o){return '<option value="'+o[0]+'">'+o[1]+'</option>';}).join('')+'</select>'
      +'<input class="ai-dm-fval" data-dm-fval placeholder="值（为空/不为空可留空）">'
      +'<button type="button" class="ai-report-secondary" data-dm-fadd>添加筛选</button>'
      +'<span class="ai-dm-chips" data-dm-chips></span>'
      +'</div>'
      +'<div class="ai-data-preview-body" data-preview-body><div class="ai-data-preview-loading">读取中…</div></div>'
      +'<div class="ai-dm-foot">'
      +'<span class="ai-dm-pager"><button type="button" class="ai-report-icon-button" data-dm-prev title="上一页">‹</button>'
      +'<span data-dm-page>1 / 1</span>'
      +'<button type="button" class="ai-report-icon-button" data-dm-next title="下一页">›</button></span>'
      +'<span class="ai-dm-count" data-dm-count></span>'
      +'<span class="ai-dm-flex"></span>'
      +'<button type="button" class="ai-dm-danger" data-dm-delsel disabled>删除选中行</button>'
      +'<button type="button" class="ai-dm-danger" data-dm-delfilter disabled>删除筛选命中行</button>'
      +'</div>'
      +'</div>';
    document.body.appendChild(mask);
    // V6 基线：ESC + 焦点移入/归还走 wireModalOverlay；遮罩点击与 × 已由下方
    // click 委托统一处理（overlayClick:false 不重复挂）。
    function closePreview(){modalFocusBack(mask);unbindEsc(mask);if(mask.parentNode)mask.parentNode.removeChild(mask);}
    wireModalOverlay(mask,closePreview,{overlayClick:false});
    function q(sel){return mask.querySelector(sel);}
    function renderChips(){
      var host=q('[data-dm-chips]');if(!host)return;
      host.innerHTML=st.filters.map(function(f,i){
        var op=(OPS.filter(function(o){return o[0]===f.op;})[0]||[f.op,f.op])[1];
        return '<span class="ai-dm-chip">'+escapeHtml(f.column)+' '+op+' '+escapeHtml(f.value==null?'':String(f.value))
          +'<button type="button" data-dm-chip-x="'+i+'" title="移除">×</button></span>';
      }).join('');
      q('[data-dm-delfilter]').disabled=!st.filters.length||st.busy;
      q('[data-dm-delfilter]').textContent=st.filters.length
        ?('删除筛选命中行'+(st.total!=null?('（'+Number(st.total).toLocaleString('en-US')+'）'):''))
        :'删除筛选命中行';
    }
    function render(rows,rowIds){
      var body=q('[data-preview-body]');if(!body)return;
      var pages=st.total!=null?Math.max(1,Math.ceil(st.total/PAGE)):1;
      q('[data-dm-page]').textContent=st.page+' / '+pages;
      q('[data-dm-prev]').disabled=st.page<=1||st.busy;
      q('[data-dm-next]').disabled=(st.page>=pages)||(st.total!=null&&st.page*PAGE>=st.total)||st.busy;
      q('[data-dm-count]').textContent=st.total!=null?('共 '+Number(st.total).toLocaleString('en-US')+' 行'):'';
      q('[data-dm-meta]').textContent=cols.length+' 列'+(st.total!=null?(' · '+Number(st.total).toLocaleString('en-US')+' 行'):'');
      renderChips();renderSelInfo();
      if(!rows||!rows.length){body.innerHTML='<div class="ai-data-preview-loading">'+(st.filters.length?'当前筛选没有命中行。':'没有数据行。')+'</div>';return;}
      var head='<tr><th class="ai-dm-check"><input type="checkbox" data-dm-selall title="全选本页"></th>'
        +cols.map(function(c){return '<th>'+escapeHtml(c)+'</th>';}).join('')+'</tr>';
      var trs=rows.map(function(r,i){
        var rid=rowIds?rowIds[i]:null;
        var key=srv?String(rid):String(rowIds[i]);
        return '<tr'+(st.sel[key]?' class="is-sel"':'')+'>'
          +'<td class="ai-dm-check"><input type="checkbox" data-dm-row="'+escapeHtml(key)+'"'+(st.sel[key]?' checked':'')+'></td>'
          +cols.map(function(_,j){
            var v=r?r[j]:null;
            return '<td title="'+escapeHtml(v==null?'':String(v))+'">'+escapeHtml(v==null?'':String(v))+'</td>';
          }).join('')+'</tr>';
      }).join('');
      body.innerHTML='<div class="ai-data-preview-scroll"><table class="ai-data-preview-table ai-dm-table"><thead>'+head+'</thead><tbody>'+trs+'</tbody></table></div>';
      var sa=body.querySelector('[data-dm-selall]');
      if(sa){
        sa.checked=rows.every(function(_,i){return st.sel[String(rowIds[i])];});
        sa.addEventListener('change',function(){
          rows.forEach(function(_,i){
            var key=String(rowIds[i]);
            if(sa.checked)st.sel[key]=true;else delete st.sel[key];
          });
          render(rows,rowIds);
        });
      }
    }
    function renderSelInfo(){
      var n=Object.keys(st.sel).length;
      var b=q('[data-dm-delsel]');
      b.disabled=!n||st.busy;
      b.textContent=n?('删除选中行（'+n+'）'):'删除选中行';
    }
    function localRows(){
      // 返回 [原下标, 行] 对：筛选后仍保留 ds.rows 里的原始下标，删选中的行
      // 才能删对（先投影再丢下标，splice 会删错行）。cols 就是 ds.columns 的
      // 顺序，行无需再投影。
      var ds=datasetById(d.id)||d;
      var pairs=(ds.rows||[]).map(function(r,i){return [i,r];});
      if(st.filters.length&&adapter&&typeof adapter.filteredRows==='function'){
        var rowsOnly=pairs.map(function(p){return p[1];});
        var kept=adapter.filteredRows({rows:rowsOnly,columns:cols,filter:st.filters});
        // 按引用反查原下标——必须用 Map：对象键会把内容相同的不同行折叠。
        var seen=new Map();
        pairs.forEach(function(p){seen.set(p[1],p[0]);});
        pairs=kept.map(function(r){return [seen.get(r),r];});
      }
      return pairs;
    }
    function load(){
      st.busy=true;renderSelInfo();
      if(!srv){
        var pairs=localRows();
        st.total=pairs.length;
        var start=(st.page-1)*PAGE;
        var pagePairs=pairs.slice(start,start+PAGE);
        st.busy=false;
        render(pagePairs.map(function(p){return p[1];}),pagePairs.map(function(p){return p[0];}));
        return;
      }
      fetch(normalizeServerBase()+'/datasets/'+encodeURIComponent(d.id)+'/rows',{
        method:'POST',headers:{'Content-Type':'application/json'},
        body:JSON.stringify({columns:cols,page:st.page,pageSize:PAGE,filter:st.filters,includeRowIds:true})})
        .then(function(r){return assertRespOk(r,'读取数据');})
        .then(function(res){
          st.busy=false;
          st.total=(res&&res.total!=null)?res.total:null;
          st.rowIds=(res&&res.rowIds)||[];
          render((res&&res.rows)||[],st.rowIds);
        })
        .catch(function(err){
          st.busy=false;
          var body=q('[data-preview-body]');
          if(body)body.innerHTML='<div class="ai-data-preview-loading">读取失败：'+escapeHtml(err&&err.message||'未知错误')+'</div>';
        });
    }
    // 服务端行删除后的报告侧收尾（与 applyUpdatedDataset server 分支同契约）。
    function afterServerDelete(res){
      var ds=datasetById(d.id);
      try{Object.keys(sampleCache).forEach(function(k){delete sampleCache[k];});}catch(e){}
      if(ds){
        if(res&&res.rowCount!=null)ds.rowCount=res.rowCount;
        invalidateColumnStats(ds);
        (manifest.charts||[]).forEach(function(chart){
          var data=(chart.editor&&chart.editor.data)||{};
          if(data.datasetId===ds.id)renderChart(chart);
        });
      }
      if(typeof renderFixedTables==='function')renderFixedTables();
      if(typeof syncManifest==='function')syncManifest();
      var msg='已删除 '+((res&&res.deleted)!=null?Number(res.deleted).toLocaleString('en-US'):'?')+' 行，'
        +'剩余 '+((res&&res.rowCount)!=null?Number(res.rowCount).toLocaleString('en-US'):'?')+' 行（已固化到服务端）。';
      if(res&&res.rematerialized&&res.rematerialized.length)msg+='关联宽表已重新合并。';
      notify(msg,'success');
    }
    function serverDelete(payload,done){
      st.busy=true;renderSelInfo();renderChips();
      fetch(normalizeServerBase()+'/datasets/'+encodeURIComponent(d.id)+'/rows/delete',{
        method:'POST',headers:{'Content-Type':'application/json'},
        body:JSON.stringify(Object.assign({password:serverEditPassword()},payload))})
        .then(function(r){return assertRespOk(r,'删除行');})
        .then(function(res){st.busy=false;afterServerDelete(res);st.sel={};st.page=1;load();if(done)done();})
        .catch(function(err){
          st.busy=false;renderSelInfo();renderChips();
          var m=(err&&err.message)||'';
          // 「筛选命中了整表」是唯一可就地补救的 400：确认后带 allowAll 重试一次。
          if(payload.mode==='filter'&&m.indexOf('整表删除')>=0
             &&global.confirm('该筛选命中了全部 '+Number(st.total).toLocaleString('en-US')
               +' 行（整表清空）。确定要删除这张表的所有行吗？')){
            serverDelete(Object.assign({},payload,{allowAll:true}),done);
            return;
          }
          notify('删除失败：'+(m||'未知错误')+'（未改动服务器上的任何数据）','error');
        });
    }
    mask.addEventListener('click',function(ev){
      if(ev.target===mask||(ev.target.closest&&ev.target.closest('[data-preview-close]'))){closePreview();return;}
      var t=ev.target;
      if(!t.closest)return;
      var chipX=t.closest('[data-dm-chip-x]');
      if(chipX){st.filters.splice(Number(chipX.getAttribute('data-dm-chip-x')),1);st.page=1;load();return;}
      if(t.closest('[data-dm-fadd]')){
        var col=q('[data-dm-fcol]').value,op=q('[data-dm-fop]').value,val=q('[data-dm-fval]').value;
        if(op!=='is null'&&op!=='is not null'&&val===''){notify('请输入筛选值（为空/不为空不需要值）。','info');return;}
        if(st.filters.length>=10){notify('筛选条件最多 10 条。','info');return;}
        st.filters.push({column:col,op:op,value:val===''?null:val});
        q('[data-dm-fval]').value='';st.page=1;load();return;
      }
      if(t.closest('[data-dm-prev]')){if(!st.busy&&st.page>1){st.page--;load();}return;}
      // busy 闸：翻页双击在 render 禁用按钮生效前会连跳两页（渲染竞态落在页外 →
      // 空表体 + 「3 / 2」页码）。load() 同步置 busy，这里就地挡住即可。
      if(t.closest('[data-dm-next]')){if(!st.busy){st.page++;load();}return;}
      var rowCb=t.closest('[data-dm-row]');
      if(rowCb){
        var key=rowCb.getAttribute('data-dm-row');
        if(rowCb.checked)st.sel[key]=true;else delete st.sel[key];
        renderSelInfo();return;
      }
      var delSel=t.closest('[data-dm-delsel]');
      if(delSel&&!delSel.disabled){
        var n=Object.keys(st.sel).length;if(!n)return;
        if(!global.confirm('删除选中的 '+n+' 行？此操作会固化到数据源，不可撤销。'))return;
        if(!srv){
          var ds=datasetById(d.id);
          if(!ds||!Array.isArray(ds.rows))return;
          var idxs=Object.keys(st.sel).map(Number).filter(function(x){return !isNaN(x);}).sort(function(a,b){return b-a;});
          idxs.forEach(function(i){ds.rows.splice(i,1);});
          st.sel={};
          try{Object.keys(sampleCache).forEach(function(k){delete sampleCache[k];});}catch(e){}
          invalidateColumnStats(ds);applyDerivedToDataset(ds);applyDimGroupsToDataset(ds);
          (manifest.charts||[]).forEach(function(chart){
            var data=(chart.editor&&chart.editor.data)||{};
            if(data.datasetId===ds.id)renderChart(chart);
          });
          if(typeof renderFixedTables==='function')renderFixedTables();
          if(typeof syncManifest==='function')syncManifest();
          notify('已删除 '+idxs.length+' 行，剩余 '+ds.rows.length+' 行。请在「保存与分享」里保存最新版本。','success');
          st.page=1;load();return;
        }
        serverDelete({mode:'rowids',rowIds:Object.keys(st.sel).map(Number)});
        return;
      }
      var delFil=t.closest('[data-dm-delfilter]');
      if(delFil&&!delFil.disabled&&st.filters.length){
        var totalTxt=st.total!=null?Number(st.total).toLocaleString('en-US'):'?';
        if(!global.confirm('删除当前筛选命中的 '+totalTxt+' 行？此操作会固化到数据源，不可撤销。'))return;
        serverDelete({mode:'filter',filter:st.filters,confirmCount:st.total!=null?st.total:undefined});
      }
    });
    load();
  }
  // 字段引用反查。注意：这里的注释**不能**以四连横向短线的注释前缀开头 ——
  // 测试按该前缀切「数据配置画布」代码块，会把本区误判成块边界，导致其后的
  // 函数（semWriteSemanticsToDs 等）不被注入沙箱、测试报 ReferenceError。
  // 「这个字段改角色/改名/删掉会影响到什么」是字段配置里最常问、也最查不到的
  // 事。纯函数列出**所有引用点**（图表 / 指标卡 / 派生定义 / 筛选器 / 合并键），
  // UI 只负责展示 + 点击定位。列名一律用**源列名**（别名只在展示层，见 colAliasOf）。
  function fieldRefs(ds,col){
    if(!col)return [];
    var out=[];
    var dsId=(ds&&ds.id)||'';
    function sameDs(id){
      if(!id||!dsId)return true;                       // schema-only/单表：不区分
      if(id===dsId)return true;
      // 大宽表 id = '<root>__wide'，图表可能记的是源表 id（合并前）——两者都算。
      return String(dsId).indexOf(String(id))===0||String(id).indexOf(String(dsId))===0
        ||String(dsId).replace(/__wide$/,'')===String(id).replace(/__wide$/,'');
    }
    function chartBlockId(c){
      if(c&&c.blockId)return c.blockId;
      var b=(manifest.blocks||[]).filter(function(x){return x&&x.chartId&&c&&x.chartId===c.id;})[0];
      return (b&&b.id)||('block-'+(c&&c.id||''));
    }
    function push(o){ if(!out.some(function(x){return x.kind===o.kind&&x.id===o.id&&x.detail===o.detail;}))out.push(o); }
    (manifest.charts||[]).forEach(function(c){
      var d=(c.editor&&c.editor.data)||{};
      if(!sameDs(d.datasetId))return;
      var hits=[];
      var dims=[].concat(d.dimension?[d.dimension]:[],d.dimensions||[]);
      if(dims.indexOf(col)>=0)hits.push('维度');
      if((d.measures||[]).indexOf(col)>=0)hits.push('指标');
      var r=d.roles||{};
      if(r.breakdown===col)hits.push('拆分');
      if(r.source===col)hits.push('X 轴');
      if(r.target===col)hits.push('Y 轴');
      if(d.table&&(d.table.detailFields||[]).indexOf(col)>=0)hits.push('明细列');
      var bp=String((d.dimensionBucket&&d.dimensionBucket.source)||'');
      if(bp===col)hits.push('时间分桶源');
      if(hits.length)push({kind:'chart',id:chartBlockId(c),label:c.title||c.id,detail:hits.join(' · '),blockId:chartBlockId(c)});
    });
    (manifest.kpis||[]).forEach(function(kp,i){
      if(!kp||!sameDs(kp.datasetId))return;
      var hits=[];
      if(kp.measure===col)hits.push('指标');
      if(kp.compareMeasure===col)hits.push('对比指标');
      var b=(manifest.blocks||[]).filter(function(x){return x&&x.kind==='kpi'&&x.kpiIndex===i;})[0];
      if(hits.length)push({kind:'kpi',id:(b&&b.id)||('block-kpi-'+i),label:kp.title||('指标卡 '+(i+1)),detail:hits.join(' · '),blockId:(b&&b.id)||('block-kpi-'+i)});
    });
    (manifest.datasets||[]).forEach(function(d){
      if(d&&d.id&&dsId&&!sameDs(d.id))return;
      var dv=d&&d.derived||{};
      (dv.columns||[]).forEach(function(cd){
        if(!cd)return;
        var refs=derivedExprRefs(cd.expr||{});
        if(refs.indexOf(col)>=0)push({kind:'derived-column',id:cd.name||cd.column||'',label:(cd.name||cd.column||'计算列'),detail:'计算列引用',dsId:d.id});
      });
      (dv.measures||[]).forEach(function(md){
        if(!md)return;
        var node=md.node||md;
        var refs=derivedNodeRefsAll(node);
        if(refs.indexOf(col)>=0)push({kind:'derived-measure',id:md.name||md.token||'',label:(md.label||md.name||'派生指标'),detail:'派生指标引用',dsId:d.id});
      });
    });
    // 派生定义也可能挂在图表上（旧 manifest / 未保存态）
    (manifest.charts||[]).forEach(function(c){
      var dm=((c.editor&&c.editor.data)||{}).derivedMeasures||{};
      Object.keys(dm).forEach(function(tk){
        if(derivedNodeRefsAll(dm[tk]).indexOf(col)>=0)push({kind:'derived-measure',id:chartBlockId(c)+':'+tk,label:(dm[tk]&&(dm[tk].label||dm[tk].name))||tk,detail:'图表内派生指标',blockId:chartBlockId(c)});
      });
    });
    (manifest.filters||[]).forEach(function(f){
      if(!f)return;
      if(f.column===col)push({kind:'filter',id:'filter:'+col,label:'筛选条件（请求声明）',detail:'作者声明',blockId:'block-filter'});
    });
    (manifest.blocks||[]).forEach(function(b){
      if(!b||b.component!=='filter')return;
      if((b.filterCols||[]).indexOf(col)>=0)push({kind:'filter',id:b.id,label:(b.title||'筛选器'),detail:'筛选条',blockId:b.id});
    });
    (manifest.relations||[]).forEach(function(rel){
      if(!rel)return;
      (rel.keys||[]).forEach(function(k){
        if(!k)return;
        if(k.a&&k.a.col===col)push({kind:'relation',id:(rel.id||rel.name||'relation')+':a',label:(rel.name||'合并关系'),detail:'合并键（本表）'});
        if(k.b&&k.b.col===col)push({kind:'relation',id:(rel.id||rel.name||'relation')+':b',label:(rel.name||'合并关系'),detail:'合并键（对端表）'});
      });
    });
    return out;
  }
  // 节点引用（含 window 的 input.ref / base），供上面的反查统一用
  function derivedNodeRefsAll(node){
    if(!node)return [];
    var out=[];
    if(node.kind==='formula'){derivedExprRefs(node.expr||{},out);}
    else{
      var ins=[].concat(node.input?[node.input]:[],node.base?[node.base]:[]);
      ins.forEach(function(i){if(i&&i.ref!==undefined&&out.indexOf(i.ref)<0)out.push(i.ref);});
    }
    return out;
  }
  function fieldRefsHtml(ds,col){
    var refs=fieldRefs(ds,col);
    if(!refs.length)return '<button type="button" class="ai-sem-col-refs is-none" data-col-refs="'+escapeHtml(col)+'" title="还没有图表 / 指标卡 / 派生定义引用这个字段">未被引用</button>';
    var kinds={};refs.forEach(function(r){kinds[r.kind]=(kinds[r.kind]||0)+1;});
    var charts=(kinds.chart||0);
    var txt=charts?('被 '+charts+' 张图表引用'):('被引用 '+refs.length+' 处');
    if(refs.length>charts)txt+='（共 '+refs.length+' 处）';
    return '<button type="button" class="ai-sem-col-refs" data-col-refs="'+escapeHtml(col)+'" title="查看引用这个字段的图表 / 指标卡 / 派生定义 / 筛选器">'+escapeHtml(txt)+'</button>';
  }
  // 字段详情展开条（Quick BI UI 对齐 §2B，2026-09-15）：「引用」徽标点击不再是
