    var modal=document.createElement('div');
    modal.id='ai-hier-canvas';
    modal.className='ai-hier-canvas-overlay';
    // ESC = 取消（与底部「取消」按钮同一路径：回滚快照），这是桌面软件的肌肉记忆。
    // V6 基线：焦点移入卡片容器（overlayClick:false——画布近全屏且取消会回滚整个
    // 会话，误点边缘就触发 confirm/回滚得不偿失，遮罩点击关闭不给）。
    modal.setAttribute('data-ai-runtime-transient','true');
