    // 「画布模式」是唯一切换（toggle），打开后右侧 = 画布。
    semCanvas.canvasMode=false;
    modal.innerHTML='<div class="ai-hier-canvas-card ai-sem-canvas-card ai-dsc-card">'
      +'<div class="ai-hier-canvas-head"><span class="ai-report-help-title">数据源配置</span><button class="ai-report-icon-button" data-canvas-close title="关闭">×</button></div>'
      +'<div class="ai-dsc-layout">'
      +'<aside class="ai-dsc-sidebar">'
      +'<div class="ai-dsc-side-head"><span class="ai-dsc-side-title">数据表</span></div>'
      // 表多了（合并组 + 补充表）先能搜：只过滤 DOM 行，不重渲染（不丢焦点）。
      +'<div class="ai-dsc-side-search"><input class="ai-sem-search" type="search" id="ai-dsc-table-search" '
      +'placeholder="搜索数据表…" aria-label="搜索数据表" value="'+escapeHtml(semCanvas.tableSearch||'')+'"></div>'
      +'<div class="ai-dsc-tables" id="ai-dsc-tables"></div>'
      +'<div class="ai-dsc-side-foot">'
      +'<button type="button" class="ai-dsc-foot-btn" data-canvas-action="add-table" title="添加一张新表">+ 添加表</button>'
      +'<button type="button" class="ai-dsc-foot-btn" data-canvas-action="add-rel" title="新建合并关联">+ 新增关联</button>'
      +'<button type="button" class="ai-dsc-foot-btn ai-dsc-toggle" id="ai-dsc-canvas-toggle" data-canvas-action="canvas-mode" title="切换右侧为表与关系画布">画布模式</button>'
      +'</div>'
      +'</aside>'
      +'<section class="ai-dsc-main">'
      +'<div class="ai-dsc-title"><h2 id="ai-dsc-main-title">字段配置</h2></div>'
      +'<div class="ai-dsc-body">'
      +'<div class="ai-sem-dsmap-block" id="ai-dsc-relations" hidden><div class="ai-sem-dsmap" id="ai-sem-dsmap"></div></div>'
      +'<div class="ai-sem-stage" id="ai-sem-stage"></div>'
      +'</div>'
      +'</section>'
      +'</div>'
      +'<div class="ai-hier-canvas-foot"><button type="button" class="ai-report-primary" data-canvas-action="save">完成</button><button type="button" class="ai-report-secondary" data-canvas-action="cancel">放弃本次改动</button></div>'
      +'</div>';
    document.getElementById('ai-report-runtime-ui').appendChild(modal);
    // V6 基线：ESC=取消（bindEsc 单一口）+ 焦点移入。必须在 append 之后调：
    // 焦点移入要找已渲染的卡片容器。
    wireModalOverlay(modal,function(){semCanvasAction('cancel');},{overlayClick:false});
    semCanvas.active=true;
    modal.addEventListener('click',function(ev){
      if(ev.target===modal||ev.target.closest('[data-canvas-close]')){closeSemCanvas();return;}
      var act=ev.target.closest('[data-canvas-action]');
      if(act)semCanvasAction(act.getAttribute('data-canvas-action'));
    });
    bindSemTableList(modal);
    renderSemTableList();
    renderSemCanvas();
