    item.className='grid-stack-item';item.setAttribute('data-report-block','chart');item.setAttribute('data-report-block-id',blockId);item.setAttribute('gs-x',String(gx));item.setAttribute('gs-y',String(gy));item.setAttribute('gs-w',String(gw));item.setAttribute('gs-h',String(gh));
    item.innerHTML='<div class="grid-stack-item-content ai-report-bi-card"><h3 data-editable-text="true">'+escapeHtml(spec.title||'新建 BI 图表')+'</h3><div id="'+elementId+'" class="chart-host"></div></div>';
    var newChartData={datasetId:dataset.id,dimension:dimensions[0],measures:[numeric[0]],aggregation:'sum',measureTypes:{}};
    if(spec.breakdown&&dimensions[1])newChartData.breakdown=dimensions[1];
