      if(a==='presentation-mode'){if(draftBlocksExport())return;if(global.AIReportPresentation)global.AIReportPresentation.toggle();}
      else if(a==='pptx-image'){if(draftBlocksExport()||!global.AIReportPPTX)return;exportPptxWithFeedback(aEl,function(){return global.AIReportPPTX.exportImage();});}
      else if(a==='pptx-native'){if(draftBlocksExport()||!global.AIReportPPTX)return;exportPptxWithFeedback(aEl,function(){return global.AIReportPPTX.exportNative();});}
      else if(a==='pdf-export'){if(draftBlocksExport())return;if(global.AIReportPresentation&&global.AIReportPresentation.exportPDF)global.AIReportPresentation.exportPDF();}
      else if(a==='help')toggleHelp();
