          var asNew=global.confirm('新文件的列结构与当前数据源不同。\n\n确定 = 作为「新数据源」追加（不破坏现有图表，之后可在数据配置里画跨表对齐）\n取消 = 打开列映射向导，把新文件映射到当前数据源');
          if(asNew){try{var nds=appendNewDataset(table,(file.name||'新数据源').replace(/\.(xlsx|csv|tsv|json)$/i,''));notify('已追加新数据源「'+nds.label+'」（'+nds.columns.length+' 列 × '+nds.rows.length+' 行）。可在「数据配置」里配置字段角色并新增跨表对齐。','success');}catch(err){alert('追加失败：'+err.message);}}
          else{openColumnWizard(ds,table);}
