  document.getElementById('ai-report-runtime-panel').addEventListener('change',function(event){
    var el=event.target;
    if(!el.matches&&!el.matches('[data-bi-control]'))return;
    if(!el.matches('[data-bi-control]'))return;
    // 目标值：写入 data.targets[measure]，再重聚合重绘（表格加目标/完成率列）。
    if(el.classList&&el.classList.contains('ai-report-chip-target')){
      var tm=el.getAttribute('data-measure');
      var ts=selected&&selected.chart&&selected.chart.editor&&selected.chart.editor.data;
      if(ts){if(!ts.targets)ts.targets={};if(el.value===''||el.value==null)delete ts.targets[tm];else ts.targets[tm]=Number(el.value);}
      updateChart();return;
    }
    // 参考线 dropdown: toggle the 目标值 number input in place (no panel
    // re-render, so the select never flashes/closes).
    if(el.classList&&el.classList.contains('ai-report-chip-ref')){
      var measure=el.getAttribute('data-measure');
      var ctl=el.closest('.ai-report-chip-ctl');
      if(ctl){
        var goalInput=ctl.querySelector('.ai-report-chip-refgoal');
        if(el.value==='goal'&&!goalInput){
          var gi=document.createElement('input');
          gi.type='number';
          gi.className='ai-report-chip-refgoal';
          gi.setAttribute('data-bi-control','true');
          gi.setAttribute('data-bi-control-action','chip-input');
          gi.setAttribute('data-measure',measure);
          gi.setAttribute('placeholder','数值');
          el.parentNode.appendChild(gi);
        }else if(el.value!=='goal'&&goalInput){goalInput.parentNode.removeChild(goalInput);}
      }
    }
    if(el.classList&&el.classList.contains('ai-chart-rel-ds')){
      var chart2=selected&&selected.chart;
      if(chart2){
        var primary2=chart2.editor&&chart2.editor.data&&chart2.editor.data.datasetId;
        var pn2=document.getElementById('ai-report-runtime-panel');
        var checked=Array.prototype.slice.call(pn2.querySelectorAll('.ai-chart-rel-ds:checked')).map(function(cb){return cb.getAttribute('data-rel-ds');});
        applyChartDatasets(chart2,[primary2].concat(checked).filter(Boolean));
      }
      return;
    }
    if(el.classList&&el.classList.contains('ai-chart-dataset')){
      switchChartDataset(el.value);
      return;
    }
    if(el.classList&&el.classList.contains('ai-tab-move')){
      relocateBlock(el.getAttribute('data-tab-move-for'),el.value);
      return;
    }
    // Y 轴单位下拉（跟轴走）：标记用户改动过，updateChart 据此只覆盖被改过的轴单位，
    // 未改过的轴保留既有 axisConfig.unit（不会把 authored 的 currency-万 覆盖成 raw）。
    if(el.classList&&el.classList.contains('ai-axis-unit')){
      el.setAttribute('data-touched','1');
      updateChart();
      return;
    }
    // 明细表 per-field 配置（小数位数/单位/目标值）：写 editor.table.fieldCfg，
    // 不走 updateChart（它从 维度/指标 隐形输入读状态，会破坏明细字段表）。
    if(el.classList&&el.classList.contains('ai-detail-cfg')){
      applyDetailFieldCfg(el);
      return;
    }
    // WP-8 行维形态：提交后重开面板——互斥联动（tree 置灰「合并同类单元格」、
    // 展示层级/合并列名/列宽的启停）由面板重渲染表达（chip-agg 重开先例同款）。
    if(el.id==='ai-table-rowform'){
      updateChart();
      if(selected&&selected.kind==='chart'){recordPanelFocus();openChart(selected.chart);restorePanelFocus();}
      return;
    }
    updateChart();
    // 指标处理 change: the per-measure controls (e.g. 小数位数, hidden for
    // count/none) depend on the aggregation, so rebuild the panel chips so the
    // option surface stays coherent with the live aggregation.
    // 系列/左-右 Y 轴 change also rebuild the panel: the「Y 轴」区块的 hasRight 依据
    // data.seriesAxis 判定，改右轴后需重渲染才会立即补出「右轴」设置。
    // R10：整面板重渲丢定位——重渲前记录焦点与滚动，渲染后恢复（连续调多指标
    // 不再反复找下拉）。
    if((el.classList&&(el.classList.contains('ai-report-chip-agg')||el.classList.contains('ai-report-chip-sertype')||el.classList.contains('ai-report-chip-seraxis')))&&selected&&selected.kind==='chart'){recordPanelFocus();openChart(selected.chart);restorePanelFocus();}
  });
  document.getElementById('ai-report-runtime-panel').addEventListener('input',function(event){if(event.target.matches('#ai-table-limit[data-bi-control]')||event.target.matches('#ai-table-grouptopn[data-bi-control]'))updateChart();});
  try{}catch(e){}
  // 先落页面宽度档位再建 grid/渲染图表：ECharts 首次量宽就必须是目标档位的宽度。
  applyShellWidth();
  document.querySelectorAll('[data-report-block]').forEach(decorateBlock);makeGrid();bindBlocks();renderFilterBar();renderAll();renderFixedTables();syncDetailBubbles();bindTabBar();dockToolbarIntoTabbar();promoteToolbarForTabOrder();recomputeTabs();activateTab('overview');(function(){var h=String(location.hash||'').replace(/^#tab-/,'');if(h&&document.querySelector('[data-tab-view="'+CSS.escape(h)+'"]'))activateTab(h);})();setEditing(isComposeDraft());bindComposeEmptyObserver();refreshDraftEmptyState();
  // 窗口宽度变化 → 表格换行/换行高变 → 重新贴合卡片高度（防出现纵向滚动条）。
  global.addEventListener('resize',function(){resizeCharts();autoFitTextBlocks();autoFitTableCards();autoFitKpiCards();refreshHScrollNotes();});
  // Apply the persisted 合并页签显示/分页 layout (default = merged; a tab is a
  // scroll anchor). Tab membership + numbering are stamped by recomputeTabs.
  if(tabsEnabled()&&document.querySelector('[data-layout-toggle]'))setReportLayout(reportLayout());
  // Fit narrative/insight text bands to their real content so a short card
  // hugs its text instead of leaving a gap below the last line.
  requestAnimationFrame(function(){autoFitTextBlocks();autoFitKpiCards();autoFitTableCards();});
  // 延迟兜底 pass：服务端明细/Σ 统计条是异步回填（占位「…」→ 真行），boot rAF 的
  // fit 量到的是占位高——late fill 之后没人重算，卡内纵向滚动条就留住了（真机
  // 900px 视口 PSI 明细卡）。只重复测量+贴合，幂等。
  setTimeout(function(){autoFitTextBlocks();autoFitTableCards();autoFitKpiCards();},1200);
  // Server-mode KPIs are data-bound with no compile-time value (the compiler
  // never saw raw rows), yet nothing recomputes them at boot — they stay "—"
  // until a filter changes. Recompute once the KPI hosts and the primary
  // dataset exist (singlefile re-runs the identical safe math, so this pass is
  // idempotent there). Guarded by a bounded retry so a slow aggregate boot
